import{_ as i,c as r,o as n,a2 as t}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Nutzungsanleitung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/usage.md","filePath":"de/guide/usage.md","lastUpdated":1793163976000}'),a={name:"de/guide/usage.md"};function l(o,e,s,h,u,d){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="nutzungsanleitung" tabindex="-1">Nutzungsanleitung <a class="header-anchor" href="#nutzungsanleitung" aria-label="Permalink to &quot;Nutzungsanleitung&quot;">​</a></h1><h2 id="archive-offnen" tabindex="-1">Archive öffnen <a class="header-anchor" href="#archive-offnen" aria-label="Permalink to &quot;Archive öffnen&quot;">​</a></h2><h3 id="per-doppelklick-offnen" tabindex="-1">Per Doppelklick öffnen <a class="header-anchor" href="#per-doppelklick-offnen" aria-label="Permalink to &quot;Per Doppelklick öffnen&quot;">​</a></h3><p>NueZip registriert sich als Standardhandler für alle unterstützten Archivformate. Doppelklicken Sie einfach auf eine beliebige Archivdatei (<code>.zip</code>, <code>.rar</code>, <code>.7z</code>, <code>.tar</code>, <code>.gz</code>, <code>.bz2</code>, <code>.xz</code>, <code>.zst</code>), um sie im Hauptfenster von NueZip zu öffnen.</p><h3 id="mit-nuezip-offnen-finder-kontextmenu" tabindex="-1">Mit NueZip öffnen (Finder-Kontextmenü) <a class="header-anchor" href="#mit-nuezip-offnen-finder-kontextmenu" aria-label="Permalink to &quot;Mit NueZip öffnen (Finder-Kontextmenü)&quot;">​</a></h3><p>Klicken Sie mit der rechten Maustaste auf eine Archivdatei und wählen Sie <strong>Mit NueZip öffnen</strong> aus dem Kontextmenü. Die Finder-Erweiterung bietet zudem Quick-Aktionen:</p><ul><li><strong>Hier extrahieren</strong> — Archivinhalte in den aktuellen Ordner extrahieren</li><li><strong>Nach „Ordnername/&quot; extrahieren</strong> — In einen benannten Unterordner extrahieren</li><li><strong>Zu ZIP komprimieren</strong> — Ausgewählte Dateien/Ordner zu einem ZIP-Archiv komprimieren</li><li><strong>Mit NueZip öffnen</strong> — Im Hauptbrowserfenster öffnen</li></ul><h3 id="per-drag-drop-auf-das-tray" tabindex="-1">Per Drag &amp; Drop auf das Tray <a class="header-anchor" href="#per-drag-drop-auf-das-tray" aria-label="Permalink to &quot;Per Drag &amp; Drop auf das Tray&quot;">​</a></h3><p>Ziehen Sie eine beliebige Archivdatei auf das NueZip-Menüleistensymbol, um sie schnell im Drop-Panel zu öffnen und sofortigen Zugriff zu erhalten. Sie können Dateien auch auf das Tray-Symbol ziehen, um sie zu komprimieren.</p><h2 id="archive-extrahieren" tabindex="-1">Archive extrahieren <a class="header-anchor" href="#archive-extrahieren" aria-label="Permalink to &quot;Archive extrahieren&quot;">​</a></h2><h3 id="grundlegende-extraktion" tabindex="-1">Grundlegende Extraktion <a class="header-anchor" href="#grundlegende-extraktion" aria-label="Permalink to &quot;Grundlegende Extraktion&quot;">​</a></h3><ol><li>Öffnen Sie ein Archiv in NueZip</li><li>Klicken Sie auf die Schaltfläche <strong>Extrahieren</strong> in der Toolbar</li><li>Wählen Sie einen Zielordner</li><li>Klicken Sie auf <strong>Extrahieren</strong></li></ol><h3 id="schnellextraktion-aus-dem-finder" tabindex="-1">Schnellextraktion aus dem Finder <a class="header-anchor" href="#schnellextraktion-aus-dem-finder" aria-label="Permalink to &quot;Schnellextraktion aus dem Finder&quot;">​</a></h3><p>Klicken Sie im Finder mit der rechten Maustaste auf ein Archiv und wählen Sie eine der Quick-Aktionen:</p><ul><li><strong>Hier extrahieren</strong> — Extrahiert direkt in den aktuellen Ordner</li><li><strong>Nach „[Archivname]/&quot; extrahieren</strong> — Extrahiert in einen benannten Unterordner für saubere Organisation</li></ul><h3 id="mit-passwort-extrahieren" tabindex="-1">Mit Passwort extrahieren <a class="header-anchor" href="#mit-passwort-extrahieren" aria-label="Permalink to &quot;Mit Passwort extrahieren&quot;">​</a></h3><p>Bei passwortgeschützten Archiven fragt NueZip nach dem Passwort. Der integrierte Passwort-Manager kann Anmeldedaten sicher in Ihrem lokalen Schlüsselbund für zukünftige Nutzung speichern.</p><h2 id="archive-komprimieren" tabindex="-1">Archive komprimieren <a class="header-anchor" href="#archive-komprimieren" aria-label="Permalink to &quot;Archive komprimieren&quot;">​</a></h2><h3 id="ein-neues-archiv-erstellen" tabindex="-1">Ein neues Archiv erstellen <a class="header-anchor" href="#ein-neues-archiv-erstellen" aria-label="Permalink to &quot;Ein neues Archiv erstellen&quot;">​</a></h3><ol><li>Wählen Sie Dateien oder Ordner im Hauptfenster von NueZip aus</li><li>Klicken Sie auf die Schaltfläche <strong>Komprimieren</strong> in der Toolbar</li><li>Wählen Sie das Archivformat (ZIP, 7z, TAR, GZIP usw.)</li><li>Konfigurieren Sie die Komprimierungseinstellungen (Stufe, Verschlüsselungsmethode)</li><li>Klicken Sie auf <strong>Komprimieren</strong></li></ol><h3 id="aus-dem-finder-komprimieren" tabindex="-1">Aus dem Finder komprimieren <a class="header-anchor" href="#aus-dem-finder-komprimieren" aria-label="Permalink to &quot;Aus dem Finder komprimieren&quot;">​</a></h3><p>Klicken Sie im Finder mit der rechten Maustaste auf Dateien/Ordner und wählen Sie <strong>Mit NueZip komprimieren</strong>:</p><ul><li><strong>Zu ZIP komprimieren</strong> — Schnelle ZIP-Archiverstellung</li><li><strong>Mit Optionen komprimieren</strong> — Öffnet NueZip mit erweiterten Einstellungen</li></ul><h3 id="per-drag-drop-komprimieren" tabindex="-1">Per Drag &amp; Drop komprimieren <a class="header-anchor" href="#per-drag-drop-komprimieren" aria-label="Permalink to &quot;Per Drag &amp; Drop komprimieren&quot;">​</a></h3><p>Ziehen Sie Dateien auf das NueZip-Menüleistentray-Symbol, um schnell ein ZIP-Archiv zu erstellen.</p><h2 id="stapelverarbeitung" tabindex="-1">Stapelverarbeitung <a class="header-anchor" href="#stapelverarbeitung" aria-label="Permalink to &quot;Stapelverarbeitung&quot;">​</a></h2><h3 id="stapelkomprimierung" tabindex="-1">Stapelkomprimierung <a class="header-anchor" href="#stapelkomprimierung" aria-label="Permalink to &quot;Stapelkomprimierung&quot;">​</a></h3><ol><li>Wählen Sie mehrere Elemente in NueZip aus</li><li>Wählen Sie <strong>Stapelkomprimierung</strong> aus der Toolbar oder dem Datei-Menü</li><li>Jedes Element wird in ein separates Archiv komprimiert</li></ol><h3 id="stapelextraktion" tabindex="-1">Stapelextraktion <a class="header-anchor" href="#stapelextraktion" aria-label="Permalink to &quot;Stapelextraktion&quot;">​</a></h3><ol><li>Wählen Sie mehrere Archive in NueZip aus</li><li>Wählen Sie <strong>Stapelextraktion</strong> aus der Toolbar oder dem Datei-Menü</li><li>Alle Archive werden gleichzeitig extrahiert</li></ol><h3 id="stapelkonvertierung" tabindex="-1">Stapelkonvertierung <a class="header-anchor" href="#stapelkonvertierung" aria-label="Permalink to &quot;Stapelkonvertierung&quot;">​</a></h3><ol><li>Wählen Sie ein oder mehrere Archive aus</li><li>Wählen Sie <strong>Konvertieren</strong> → Zielformat auswählen</li><li>NueZip rekomprimiert jedes Archiv in das gewählte Format</li></ol><h3 id="stapelverschlusselung" tabindex="-1">Stapelverschlüsselung <a class="header-anchor" href="#stapelverschlusselung" aria-label="Permalink to &quot;Stapelverschlüsselung&quot;">​</a></h3><ol><li>Wählen Sie mehrere ZIP-Archive aus</li><li>Wählen Sie <strong>Stapelverschlüsselung</strong></li><li>Legen Sie ein Passwort fest — alle ausgewählten Archive werden passwortgeschützt</li></ol><h2 id="formatkonvertierung" tabindex="-1">Formatkonvertierung <a class="header-anchor" href="#formatkonvertierung" aria-label="Permalink to &quot;Formatkonvertierung&quot;">​</a></h2><p>Konvertieren Sie Archive zwischen allen unterstützten Formaten:</p><ol><li>Öffnen Sie ein Archiv</li><li>Klicken Sie auf <strong>Konvertieren</strong> in der Toolbar</li><li>Wählen Sie das Zielformat (z. B. RAR → ZIP, 7z → TAR.GZ)</li><li>Wählen Sie den Ausgabespeicherort</li><li>Klicken Sie auf <strong>Konvertieren</strong></li></ol><h2 id="archiv-reparatur" tabindex="-1">Archiv-Reparatur <a class="header-anchor" href="#archiv-reparatur" aria-label="Permalink to &quot;Archiv-Reparatur&quot;">​</a></h2><p>Für beschädigte RAR- oder ZIP-Archive:</p><ol><li>Öffnen Sie das beschädigte Archiv</li><li>Klicken Sie auf <strong>Reparieren</strong> in der Toolbar</li><li>NueZip versucht, die Archivdaten zu rekonstruieren</li><li>Das reparierte Archiv wird als neue Datei gespeichert</li></ol><h2 id="archivsuche" tabindex="-1">Archivsuche <a class="header-anchor" href="#archivsuche" aria-label="Permalink to &quot;Archivsuche&quot;">​</a></h2><p>Finden Sie bestimmte Dateien innerhalb von Archiven:</p><ol><li>Klicken Sie auf die Schaltfläche <strong>Suchen</strong> in der Toolbar</li><li>Geben Sie ein Dateinamenmuster ein</li><li>NueZip durchsucht alle Einträge im geöffneten Archiv</li><li>Ergebnisse werden mit vollständigen Pfaden für schnelle Navigation angezeigt</li></ol><h2 id="leistungs-benchmark" tabindex="-1">Leistungs-Benchmark <a class="header-anchor" href="#leistungs-benchmark" aria-label="Permalink to &quot;Leistungs-Benchmark&quot;">​</a></h2><p>Testen Sie die Kompressionsleistung Ihres Systems:</p><ol><li>Gehen Sie zu <strong>Werkzeuge → Benchmark</strong></li><li>NueZip führt KompressionsTests mit verschiedenen Formaten und Einstellungen durch</li><li>Ergebnisse zeigen Kompressionsgeschwindigkeit (MB/s) und Verhältnis für jedes Format</li><li>Nutzen Sie dies, um die Leistung verschiedener Kompressionsmethoden zu vergleichen</li></ol><h2 id="multi-volume-archive-split" tabindex="-1">Multi-Volume-Archive (Split) <a class="header-anchor" href="#multi-volume-archive-split" aria-label="Permalink to &quot;Multi-Volume-Archive (Split)&quot;">​</a></h2><p>Erstellen Sie Split-Archive für große Daten:</p><ol><li>Aktivieren Sie während der Komprimierung <strong>In Volumes aufteilen</strong></li><li>Wählen Sie die Volume-Größe (z. B. 100 MB, 650 MB, 4,7 GB oder benutzerdefiniert)</li><li>NueZip erstellt nummerierte Teildateien (<code>.zip.001</code>, <code>.zip.002</code> usw.)</li><li>Zum Extrahieren öffnen Sie die erste Teildatei — NueZip lädt den Rest automatisch</li></ol><ul><li><strong>Passwort</strong>: Geben Sie ein Passwort für verschlüsselte Archive an</li><li><strong>In Ordner einbinden</strong>: Erstellt automatisch einen Stammordner, falls das Archiv kein einzelnes Stammverzeichnis hat</li><li><strong>Danach öffnen</strong>: Zeigt die extrahierten Dateien im Finder nach Abschluss an</li><li><strong>Beschädigte Dateien behalten</strong>: Bewahrt alle Dateien, die vor einem Fehler extrahiert wurden (für Teilwiederherstellung)</li><li><strong>Aktualisierungsmodus</strong>: Wählen Sie, wie mit vorhandenen Dateien umgegangen wird (überschreiben, überspringen, umbenennen)</li></ul><h3 id="stapelextraktion-1" tabindex="-1">Stapelextraktion <a class="header-anchor" href="#stapelextraktion-1" aria-label="Permalink to &quot;Stapelextraktion&quot;">​</a></h3><ol><li>Gehen Sie zu <strong>Werkzeuge → Stapelextraktion</strong></li><li>Klicken Sie auf <strong>Dateien hinzufügen...</strong>, um Archivdateien auszuwählen</li><li>Wählen Sie einen Zielordner</li><li>Aktivieren Sie optional <strong>Quelldateien nach Extraktion löschen</strong></li><li>Klicken Sie auf <strong>Start</strong></li></ol><h2 id="archive-erstellen" tabindex="-1">Archive erstellen <a class="header-anchor" href="#archive-erstellen" aria-label="Permalink to &quot;Archive erstellen&quot;">​</a></h2><h3 id="dateien-komprimieren" tabindex="-1">Dateien komprimieren <a class="header-anchor" href="#dateien-komprimieren" aria-label="Permalink to &quot;Dateien komprimieren&quot;">​</a></h3><ol><li>Klicken Sie auf die Schaltfläche <strong>Komprimieren</strong> in der Toolbar</li><li>Wählen Sie zu komprimierende Dateien aus (oder ziehen Sie sie per Drag &amp; Drop in das Fenster)</li><li>Wählen Sie <strong>Archivformat</strong>: ZIP, 7Z, TAR, GZIP, BZIP2</li><li>Konfigurieren Sie <strong>Kompressionsmethode</strong> und -stufe</li><li>Legen Sie <strong>Speicherort</strong> und Archivnamen fest</li><li>Legen Sie optional ein <strong>Passwort</strong> für die Verschlüsselung fest</li><li>Legen Sie optional <strong>Split-Größe</strong> für Multi-Volume-Archive fest</li><li>Klicken Sie auf <strong>Komprimieren</strong></li></ol><h3 id="dateien-zu-vorhandenem-archiv-hinzufugen" tabindex="-1">Dateien zu vorhandenem Archiv hinzufügen <a class="header-anchor" href="#dateien-zu-vorhandenem-archiv-hinzufugen" aria-label="Permalink to &quot;Dateien zu vorhandenem Archiv hinzufügen&quot;">​</a></h3><ol><li>Öffnen Sie ein vorhandenes Archiv in NueZip</li><li>Klicken Sie auf <strong>Dateien hinzufügen</strong> in der Toolbar</li><li>Wählen Sie hinzuzufügende Dateien aus</li><li>Klicken Sie auf <strong>Hinzufügen</strong></li></ol><h2 id="stapelverarbeitung-1" tabindex="-1">Stapelverarbeitung <a class="header-anchor" href="#stapelverarbeitung-1" aria-label="Permalink to &quot;Stapelverarbeitung&quot;">​</a></h2><h3 id="stapelkomprimierung-1" tabindex="-1">Stapelkomprimierung <a class="header-anchor" href="#stapelkomprimierung-1" aria-label="Permalink to &quot;Stapelkomprimierung&quot;">​</a></h3><ol><li>Gehen Sie zu <strong>Werkzeuge → Stapelkomprimierung</strong></li><li>Klicken Sie auf <strong>Dateien/Ordner auswählen...</strong>, um Elemente zu wählen</li><li>Jedes ausgewählte Element wird zu einem separaten Archiv</li><li>Konfigurieren Sie Ausgabe-<strong>Format</strong>, <strong>Speicherort</strong> und Dateibenennungspräfix</li><li>Klicken Sie auf <strong>Start</strong></li></ol><h3 id="stapelformatkonvertierung" tabindex="-1">Stapelformatkonvertierung <a class="header-anchor" href="#stapelformatkonvertierung" aria-label="Permalink to &quot;Stapelformatkonvertierung&quot;">​</a></h3><ol><li>Gehen Sie zu <strong>Werkzeuge → Stapelformatkonvertierung</strong></li><li>Klicken Sie auf <strong>Dateien hinzufügen...</strong>, um Quellarchive auszuwählen</li><li>Wählen Sie <strong>Zielformat</strong></li><li>Aktivieren Sie optional <strong>Quelldateien nach Konvertierung löschen</strong></li><li>Klicken Sie auf <strong>Start</strong></li></ol><h3 id="stapelverschlusselung-1" tabindex="-1">Stapelverschlüsselung <a class="header-anchor" href="#stapelverschlusselung-1" aria-label="Permalink to &quot;Stapelverschlüsselung&quot;">​</a></h3><ol><li>Gehen Sie zu <strong>Werkzeuge → Stapelverschlüsselung</strong></li><li>Klicken Sie auf <strong>Dateien hinzufügen...</strong>, um Archive auszuwählen</li><li>Geben Sie ein <strong>Passwort</strong> ein</li><li>Klicken Sie auf <strong>Verschlüsseln</strong></li></ol><h2 id="erweiterte-funktionen" tabindex="-1">Erweiterte Funktionen <a class="header-anchor" href="#erweiterte-funktionen" aria-label="Permalink to &quot;Erweiterte Funktionen&quot;">​</a></h2><h3 id="archiv-reparatur-1" tabindex="-1">Archiv-Reparatur <a class="header-anchor" href="#archiv-reparatur-1" aria-label="Permalink to &quot;Archiv-Reparatur&quot;">​</a></h3><p>Reparieren Sie beschädigte oder defekte Archive:</p><ol><li>Wählen Sie das beschädigte Archiv aus</li><li>Gehen Sie zu <strong>Werkzeuge → Archiv reparieren</strong></li><li>NueZip scannt den Header, baut das Verzeichnis neu auf und repariert Datenblöcke</li><li>Prüfen Sie das Reparaturergebnis</li></ol><h3 id="formatkonvertierung-1" tabindex="-1">Formatkonvertierung <a class="header-anchor" href="#formatkonvertierung-1" aria-label="Permalink to &quot;Formatkonvertierung&quot;">​</a></h3><p>Konvertieren Sie Archive zwischen Formaten:</p><ol><li>Öffnen Sie ein Archiv oder wählen Sie eine Datei aus</li><li>Gehen Sie zu <strong>Datei → Format konvertieren</strong></li><li>Wählen Sie Zielformat und Kompressionsstufe</li><li>Löschen Sie optional die Originaldatei</li><li>Klicken Sie auf <strong>Konvertieren</strong></li></ol><h3 id="passwort-manager" tabindex="-1">Passwort-Manager <a class="header-anchor" href="#passwort-manager" aria-label="Permalink to &quot;Passwort-Manager&quot;">​</a></h3><p>NueZip speichert Archivpasswörter sicher in Ihrem lokalen Schlüsselbund:</p><ol><li>Gehen Sie zu <strong>Werkzeuge → Passwort-Manager</strong></li><li>Zeigen Sie alle gespeicherten Passwörter an</li><li>Fügen, bearbeiten oder löschen Sie Einträge</li><li>Passwörter werden beim Öffnen passender verschlüsselter Archive automatisch angewendet</li></ol><h3 id="leistungs-benchmark-1" tabindex="-1">Leistungs-Benchmark <a class="header-anchor" href="#leistungs-benchmark-1" aria-label="Permalink to &quot;Leistungs-Benchmark&quot;">​</a></h3><p>Testen Sie die Kompressionsleistung Ihres Systems:</p><ol><li>Gehen Sie zu <strong>Werkzeuge → Leistungs-Benchmark</strong></li><li>Wählen Sie eine Testdatei (oder verwenden Sie die Standarddatei)</li><li>Klicken Sie auf <strong>Test</strong></li><li>Zeigen Sie Ergebnisse einschließlich Komprimier-/Dekomprimierungsgeschwindigkeit und Bewertung an</li></ol><h3 id="archivsuche-1" tabindex="-1">Archivsuche <a class="header-anchor" href="#archivsuche-1" aria-label="Permalink to &quot;Archivsuche&quot;">​</a></h3><p>Finden Sie Dateien innerhalb von Archiven:</p><ol><li>Öffnen Sie ein Archiv</li><li>Drücken Sie <code>Cmd+F</code> oder klicken Sie auf das Suchsymbol</li><li>Geben Sie einen Dateinamen ein, optional mit Groß-/Kleinschreibung oder ganzes Wort</li><li>Durchsuchen Sie die Ergebnisse und klicken Sie zur Navigation</li></ol><h2 id="tastenkurzel" tabindex="-1">Tastenkürzel <a class="header-anchor" href="#tastenkurzel" aria-label="Permalink to &quot;Tastenkürzel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Aktion</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Archiv öffnen</td></tr><tr><td><code>Cmd+N</code></td><td>Neues Archiv</td></tr><tr><td><code>Cmd+E</code></td><td>Extrahieren</td></tr><tr><td><code>Cmd+F</code></td><td>Im Archiv suchen</td></tr><tr><td><code>Cmd+,</code></td><td>Einstellungen öffnen</td></tr><tr><td><code>Cmd+W</code></td><td>Fenster schließen</td></tr><tr><td><code>Cmd+Q</code></td><td>Anwendung beenden</td></tr><tr><td><code>Cmd+↑</code></td><td>Eine Ebene nach oben</td></tr><tr><td><code>Cmd+→</code></td><td>Vorwärts gehen</td></tr></tbody></table><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Greifen Sie über <strong>NueZip → Einstellungen</strong> auf die Einstellungen zu oder drücken Sie <code>Cmd+,</code>:</p><ul><li><strong>Allgemein</strong>: Sprache, Start bei Anmeldung, Erscheinungsbild-Theme</li><li><strong>Komprimierung</strong>: Standardformat, Kompressionsstufe, Split-Größe</li><li><strong>Extraktion</strong>: Standardziel, Einbindungsverhalten, Konfliktauflösung</li><li><strong>Ordnerzugriff</strong>: Ordnerberechtigungen und Lesezeichen verwalten</li><li><strong>Erweitert</strong>: Hardwarebeschleunigung, Thread-Anzahl, temporäres Verzeichnis</li><li><strong>Datenschutz</strong>: Datenerfassungspräferenzen</li></ul>',85)])])}const m=i(a,[["render",l]]);export{g as __pageData,m as default};
